import axios from 'axios';
import authHeader from './authHeader';

const API_URL = '/api/orders';

// 获取所有订单 (管理员)
const getOrders = () => {
  return axios.get(API_URL, { headers: authHeader() });
};

// 获取我的订单
const getMyOrders = () => {
  return axios.get(`${API_URL}/my`, { headers: authHeader() });
};

// 创建回收订单
const createRecycleOrder = (orderData) => {
  return axios.post(`${API_URL}/recycle`, orderData, { headers: authHeader() });
};

// 创建购买订单
const createPurchaseOrder = (phoneId) => {
  return axios.post(
    `${API_URL}/purchase`,
    { phoneId },
    { headers: authHeader() }
  );
};

// 更新订单状态 (管理员)
const updateOrderStatus = (id, status) => {
  return axios.put(
    `${API_URL}/${id}/status`,
    { status },
    { headers: authHeader() }
  );
};

// 获取所有订单 (仅管理员)
const getAllOrders = async () => {
  try {
    const response = await axios.get(API_URL, { headers: authHeader() });
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || '获取订单失败';
  }
};

const updateOrder = async (orderId, updateData) => {
  try {
    const response = await axios.put(
      `${API_URL}/${orderId}`,
      updateData,
      { headers: authHeader() }
    );
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || '更新订单失败';
  }
};

const deleteOrder = async (orderId) => {
  try {
    const response = await axios.delete(`${API_URL}/${orderId}`, { headers: authHeader() });
    return response.data;
  } catch (error) {
    throw error.response?.data?.message || '删除订单失败';
  }
};

const orderService = {
  getOrders,
  getMyOrders,
  createRecycleOrder,
  createPurchaseOrder,
  updateOrderStatus,
  getAllOrders,
  updateOrder,
  deleteOrder,
};

export default orderService;
